void integer(std::vector<unsigned char>& b,std::uint64_t n){for(int i=0;i<8;++i)b.push_back((n>>(8*i))&255);}
void text(std::vector<unsigned char>& b,const std::string& s){integer(b,s.size());b.insert(b.end(),s.begin(),s.end());}
