std::string sha(const std::vector<unsigned char>& bytes){unsigned char d[32];unsigned n=0;auto* ctx=EVP_MD_CTX_new();need(ctx&&EVP_DigestInit_ex(ctx,EVP_sha256(),nullptr)==1&&EVP_DigestUpdate(ctx,bytes.data(),bytes.size())==1&&EVP_DigestFinal_ex(ctx,d,&n)==1&&n==32,"test hash");EVP_MD_CTX_free(ctx);std::string s;const char* h="0123456789abcdef";for(auto c:d){s.push_back(h[c>>4]);s.push_back(h[c&15]);}return s;}
